public class UPSVendPriceAdmCopy extends RunBase
{
    #DEFINE.CurrentVersion(1)
    #LOCALMACRO.CurrentList
        chgItemCode,
        chgACCode,
        chgACRelation,
        newItemCode,
        newACCode,
        newACRelation
    #ENDMACRO

    DialogRunbase           dialog;

    QueryRun                queryRun;
    Counter                 progressCounter;
    Counter                 progressTotal;

    DialogField             fieldChgItemCode;
    DialogField             fieldChgACCode;
    DialogField             fieldChgACRelation;

    DialogField             fieldNewItemCode;
    DialogField             fieldNewACCode;
    DialogField             fieldNewACRelation;

    NoYes                   chgItemCode;
    NoYes                   chgACCode;
    NoYes                   chgACRelation;

    ItemIdSmall             newItemCode;
    UPSVendPriceAccountCode newACCode;
    UPSVendPriceRelation    newACRelation;
    CustVendRel             prevACRel;

}

Method.Source:
private DialogField addToggleField(FieldLabel _label, FieldHelp _help)
{
    DialogField result = dialog.addField(enumStr(NoYes), _label, _help);

    result.registerOverrideMethod(methodStr(FormCheckBoxControl, modified), methodStr(UPSVendPriceAdmCopy, enableControls), this);

    return result;
}

public Object dialog()
{
    DialogGroup             dialogGroup;
    DialogGroup             chgGroup;
    DialogGroup             newGroup;
    FormBuildStringControl  newControl;

    dialog = super();

    dialogGroup = dialog.addGroup();
    chgGroup    = dialog.addGroup("@SYS138761", dialogGroup);

    fieldChgItemCode   = this.addToggleField("@SYS58740", "@SYS138766");
    fieldChgACCode     = this.addToggleField("@SYS12243", "@SYS138768");
    fieldChgACRelation = this.addToggleField("@SYS265"  , "@SYS138769");

    newGroup = dialog.addGroup("@SYS81533", dialogGroup);

    fieldNewItemCode   = dialog.addField(extendedTypeStr(ItemIdSmall), ' ', "@SYS138766");
    fieldNewACCode     = dialog.addField(enumStr(UPSVendPriceAccountCode), ' ', "@SYS138768");
    fieldNewACRelation = dialog.addField(extendedTypeStr(UPSVendPriceRelation), "@SYS2355");

    newControl = fieldNewACRelation.control();
    newControl.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(UPSVendPriceAdmCopy, fieldNewACRelation_lookup), this);
    newControl.registerOverrideMethod(methodStr(FormStringControl, resolveAmbiguousReference), methodStr(UPSVendPriceAdmCopy, fieldNewACRelation_resolveAmbiguousReference), this);

    dialogGroup.columns(2);
    dialogGroup.frameType(1);

    dialog.addMenuItemButton(MenuItemType::Display, menuitemDisplayStr(RunBaseQueryDialog), DialogMenuItemGroup::BottomGrp);

    dialog.allowUpdateOnSelectCtrl(true);

    this.enableControls(null);

    return dialog;
}

private boolean enableControls(FormCheckBoxControl _checkBoxControl)
{
    fieldNewItemCode.enabled(fieldChgItemCode.value());
    fieldNewACCode.enabled(fieldChgACCode.value());
    fieldNewACRelation.enabled(fieldChgACRelation.value());

    return true;
}

protected void displayProgress()
{
    this.progressUpdate(strFmt("@SYS60086", tableId2pname(tableNum(UPSVendPriceAdmTrans))));
}

protected void fieldNewACRelation_lookup(FormStringControl _callingControl)
{
    switch (fieldNewACCode.value())
    {
        case TableGroupAll::Table:
            VendTable::lookupVendor(_callingControl);
            break;
        case TableGroupAll::GroupId:
            UPSVendPriceGroup::vendPriceGroupIdLookup(_callingControl);
            break;
    }
}

protected str fieldNewACRelation_resolveAmbiguousReference(FormStringControl _callingControl)
{
    UPSVendPriceAdmTrans localUPSVendPriceAdmTrans;

    if (fieldNewACCode.value() == TableGroupAll::Table)
    {
        return VendTable::resolveAmbiguousReferenceVendor(_callingControl);
    }

    return _callingControl.text();
}

public boolean getFromDialog()
{
    chgItemCode   = fieldChgItemCode.value();
    chgACCode     = fieldChgACCode.value();
    chgACRelation = fieldChgACRelation.value();

    newItemCode   = fieldNewItemCode.value();
    newACCode     = fieldNewACCode.value();
    newACRelation = fieldNewACRelation.value();

    return true;
}

protected void new()
{
    super();

    queryRun = new QueryRun(queryStr(UPSVendPriceAdmTrans));
}

public container  pack()
{
    return [#CurrentVersion, #CurrentList, queryRun.pack()];
}

protected void progressUpdate(str _text)
{
    progressCounter++;
    progress.setCount(progressCounter);
    progress.setText(_text);
}

public QueryRun queryRun()
{
    return queryRun;
}

public void run()
{
    UPSVendPriceAdmTrans   upsVendPriceAdmTrans;
    RecordSortedList       upsVendPriceAdmTransList = new RecordSortedList(tableNum(UPSVendPriceAdmTrans));

    #macrolib.AviFiles

    upsVendPriceAdmTransList.sortOrder(fieldNum(UPSVendPriceAdmTrans, RecId));

    progressTotal = QueryRun::getQueryRowCount(queryRun.query(), intMax()) * 2;

    this.progressInit("@SYS59049", progressTotal, #AviFileCopy);

    progress = this.parmProgress();

    ttsbegin;

    while (queryRun.next())
    {
        this.displayProgress();

        upsVendPriceAdmTrans = queryRun.get(tableNum(UPSVendPriceAdmTrans));

        upsVendPriceAdmTransList.ins(upsVendPriceAdmTrans);
    }

    if (upsVendPriceAdmTransList.first(upsVendPriceAdmTrans))
    {
        do
        {
            this.displayProgress();
            this.updateNow(upsVendPriceAdmTrans);
        } 
        while (upsVendPriceAdmTransList.next(upsVendPriceAdmTrans));
    }

    ttscommit;
}

public boolean  unpack(container _packedClass)
{
    Integer     version     = RunBase::getVersion(_packedClass);
    container   packedQueryRun;

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList, packedQueryRun] = _packedClass;

            if (SysQuery::isPackedOk(packedQueryRun))
            {
                queryRun   = new QueryRun(packedQueryRun);
            }
            else
            {
                return false;
            }
            break;
        default :
            return false;
    }

    return true;
}

protected void updateNow(UPSVendPriceAdmTrans _upsVendPriceAdmTrans)
{
    UPSVendPriceAdmTrans newUPSVendPriceAdmTrans = this.initializeUPSVendPriceAdmTransCopy(_upsVendPriceAdmTrans);

    if (! newUPSVendPriceAdmTrans.validateWrite())
    {
        throw error("@SYS326740");
    }

    newUPSVendPriceAdmTrans.insert();
}

protected UPSVendPriceAdmTrans initializeUPSVendPriceAdmTransCopy(UPSVendPriceAdmTrans _upsVendPriceAdmTrans)
{
    UPSVendPriceAdmTrans newUPSVendPriceAdmTrans = _upsVendPriceAdmTrans.data();

    if (chgItemCode)
    {
        newUPSVendPriceAdmTrans.ItemNum = newItemCode;
    }

    if (chgACCode)
    {
        newUPSVendPriceAdmTrans.AccountCode = newACCode;
    }

    if (chgACRelation)
    {
        newUPSVendPriceAdmTrans.AccountRelation = newACRelation;
    }

    return newUPSVendPriceAdmTrans;
}

private void clearProductDimensions(UPSVendPriceAdmTrans _upsVendPriceAdmTrans)
{
    InventDim inventDim = _upsVendPriceAdmTrans.inventDim();

    if (this.shouldClearProductDimensions(inventDim))
    {
        inventDim.clearProductDimensions();

        _upsVendPriceAdmTrans.InventDimId = inventDim::findOrCreate(inventDim).inventDimId;
    }
}

private boolean shouldClearProductDimensions(InventDim _inventDim)
{
    return _inventDim.anyProductDimensionSpecified();
}

public void  updateQueryBuild(UPSVendPriceAdmTrans _upsVendPriceAdmTrans)
{
    QueryBuildRange queryBuildRange;

    queryBuildRange = queryRun.query().dataSourceTable(tableNum(UPSVendPriceAdmTrans)).findRange(fieldNum(UPSVendPriceAdmTrans, JournalNum));
    queryBuildRange.value(queryValue(_upsVendPriceAdmTrans.JournalNum));
    queryBuildRange.status(RangeStatus::Hidden);
    queryRun.title(UPSVendPriceAdmCopy::description());
}

public boolean validate(Object _calledFrom = null)
{
    return true;
}

public static UPSVendPriceAdmCopy construct()
{
    return new UPSVendPriceAdmCopy();
}

public static ClassDescription description()
{
    return "@UnifiedPricingService:UPSVendPriceAdm_CopyReviseDesc";
}

public static void main(Args args)
{
    UPSVendPriceAdmTrans upsVendPriceAdmTrans;
    UPSVendPriceAdmCopy  upsVendPriceAdmCopy = UPSVendPriceAdmCopy::construct();
    FormDataSource       formDS;

    if (!(args.dataset() == tableNum(UPSVendPriceAdmTrans)))
    {
        throw error("@SYS18626");
    }

    upsVendPriceAdmTrans = args.record();

    if (! upsVendPriceAdmTrans.JournalNum)
    {
        throw error("@SYS59048");
    }

    upsVendPriceAdmCopy.getLast();
    upsVendPriceAdmCopy.updateQueryBuild(upsVendPriceAdmTrans);

    if (upsVendPriceAdmCopy.prompt())
    {
        upsVendPriceAdmCopy.runOperation();

        if (args.record().isFormDataSource())
        {
            formDS = args.record().dataSource();
            formDS.research(true);
        }
    }
}

protected boolean canRunInNewSession()
{
    return true;
}
